-- EduNova v0.23.0 LOT 22 — Campus Core. PostgreSQL production migration.
CREATE TABLE IF NOT EXISTS campus_institutions(id varchar(64) PRIMARY KEY,slug varchar(96) UNIQUE NOT NULL,name varchar(240) NOT NULL,legal_name varchar(240) NOT NULL DEFAULT '',country_code varchar(2) NOT NULL,city varchar(120),logo_url varchar(1000),state varchar(24) NOT NULL,row_version integer NOT NULL DEFAULT 1,created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_campus_institutions_state ON campus_institutions(state);
CREATE TABLE IF NOT EXISTS campus_academic_units(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,kind varchar(24) NOT NULL,name varchar(240) NOT NULL,code varchar(64) NOT NULL,parent_id varchar(64),active boolean NOT NULL DEFAULT true,row_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT uq_campus_unit_code UNIQUE(institution_id,code));
CREATE INDEX IF NOT EXISTS ix_campus_units_tenant ON campus_academic_units(institution_id,kind,active);
CREATE TABLE IF NOT EXISTS campus_academic_periods(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,kind varchar(24) NOT NULL,name varchar(160) NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,parent_id varchar(64),active boolean NOT NULL DEFAULT true,row_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,CHECK(starts_on<ends_on));
CREATE INDEX IF NOT EXISTS ix_campus_periods_tenant ON campus_academic_periods(institution_id,starts_on);
CREATE TABLE IF NOT EXISTS campus_memberships(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,account_id varchar(64) NOT NULL,role varchar(32) NOT NULL,state varchar(24) NOT NULL,unit_id varchar(64),invited_by varchar(64),joined_at timestamptz,row_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT uq_campus_member UNIQUE(institution_id,account_id));
CREATE INDEX IF NOT EXISTS ix_campus_membership_account ON campus_memberships(account_id,state);
CREATE INDEX IF NOT EXISTS ix_campus_membership_tenant_role ON campus_memberships(institution_id,role,state);
CREATE TABLE IF NOT EXISTS campus_cohorts(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,program_unit_id varchar(64) NOT NULL,academic_period_id varchar(64) NOT NULL,name varchar(160) NOT NULL,level varchar(80) NOT NULL,active boolean NOT NULL DEFAULT true,row_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_campus_cohorts_tenant ON campus_cohorts(institution_id,academic_period_id,active);
CREATE TABLE IF NOT EXISTS campus_enrollments(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,cohort_id varchar(64) NOT NULL,student_account_id varchar(64) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,CONSTRAINT uq_campus_enrollment UNIQUE(cohort_id,student_account_id));
CREATE INDEX IF NOT EXISTS ix_campus_enrollments_tenant_student ON campus_enrollments(institution_id,student_account_id,active);
